        $_dn_init = isset($_bm_init['display_name']) ? trim((string) $_bm_init['display_name']) : '';
        if ($_dn_init !== '') {
            $bs_load_metal = $_dn_init;
            break;
        }
    }
}
$barcode_settings = ($bs_load_metal !== '') ? getBarcodeSettings($bs_load_metal) : getBarcodeSettings();
if (!$barcode_settings && $bs_load_metal !== '') {
    $barcode_settings = null;
}
$barcode_settings_by_metal_js = [];
foreach (getBarcodeSettingsByMetalMap() as $_mt_key => $_mt_row) {
    $_snap = auragold_barcode_settings_designer_snapshot($_mt_row);
    if ($_snap) {
        $barcode_settings_by_metal_js[$_mt_key] = $_snap;
    }
}

